/** El primer argumento que no empieza con `--` y no es el valor de una opción previa. */
function firstPositional(argv: string[]): string | undefined {
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i]!
    if (a.startsWith('--')) {
      i++ // consume el valor de la opción
      continue
    }
    return a
  }
  return undefined
}

